import React, { useState, useEffect } from 'react';
import { makeStyles } from '@material-ui/core/styles';
import Paper from '@material-ui/core/Paper';
import Grid from '@material-ui/core/Grid';
import CircularProgress from '@material-ui/core/CircularProgress';


const useStyles = makeStyles((theme) => ({
    root: {
        flexGrow: 1,
    },
    paper: {
        padding: theme.spacing(2),
        textAlign: 'center',
        color: theme.palette.text.secondary,
    },
}));


function FacilityDashboard({ match }) {
    const classes = useStyles();


    const [loading, setLoading] = useState(true);
    const [data, setData] = useState({});

    const fetchFacilityDashboard = async () => {

        const url = `http://patientintake.shuthuluwhiskeyroses.com/api/location/${match.params.id}`;
        const response = await fetch(url);

        const facilityDashboard = await response.json();
        console.log(facilityDashboard);

        setData(facilityDashboard);
        setLoading(false);
    }

    useEffect(() => {
        fetchFacilityDashboard();
    }, {});


    return (<div >
        {loading ? <CircularProgress /> :

            <Grid container spacing={3}>
                <Grid item xs={12}>
                    <Paper className={classes.paper}>{data.Facility.LocationDescription}</Paper>
                    <Grid item xs={12} > <Paper className={classes.paper}>
                        <div>{data.Facility.AddressLine1}</div>
                        <div>{data.Facility.AddressLine2}</div>
                        <div>{data.Facility.AddressCity}</div>
                        <div>{data.Facility.AddressState}</div></Paper>
                    </Grid>

                </Grid>

                <Grid item xs={12} sm={6}>
                    <Paper className={classes.paper}>
                        <h1>Open Encounters</h1>

                        <table>
                            <tr><th>Name</th>
                                <th>Date of Birth</th>
                                <th>Gender</th>
                                <th>Phone</th>
                                <th>Email</th>
                                <th>Notes</th></tr>

                            {data.OpenEncounters.map(encounter =>
                                <tr>
                                    <td>{encounter.Patients_FirstName} {encounter.Patients_LastName}</td>
                                    <td>{encounter.Patients_DateOfBirth}</td>
                                    <td>{encounter.Patients_Gender}</td>
                                    <td>{encounter.Patients_Phone}</td>
                                    <td>{encounter.Patients_Email}</td>
                                    <td>{encounter.Encounter_Comments}</td>
                                </tr>
                            )}
                        </table>
                    </Paper>
                </Grid>
                <Grid item xs={12} sm={6}>
                    <Paper className={classes.paper}>
                        <h1>Scheduled Providers</h1>
                        <table>
                            <tr>
                                <th>Name</th>
                                <th>Cell Phone</th>
                                <th>Office Phone</th>
                                <th>Email</th>
                                <th>Areas Of Practice</th></tr>

                            {data.Providers.map(provider =>
                                <tr>
                                    <td>{provider.Prefix}{provider.FirstName} {provider.LastName}{provider.Suffix}</td>
                                    <td>{provider.Phone}</td>
                                    <td>{provider.OfficePhone}</td>
                                    <td>{provider.Email}</td>
                                    <td>{provider.AreasOfPractice}</td>
                                </tr>
                            )}
                        </table>

                    </Paper>
                </Grid>

            </Grid>}

    </div>
    );
}

export default FacilityDashboard;
