import React , { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { Link } from 'react-router-dom';


import { makeStyles } from '@material-ui/core/styles';
import Card from '@material-ui/core/Card';
import CardActions from '@material-ui/core/CardActions';
import CardContent from '@material-ui/core/CardContent';
import Button from '@material-ui/core/Button';
import Typography from '@material-ui/core/Typography';

const useStyles = makeStyles({
    root: {
        Width: 275,
    },

    paper: {
       
    },

    bullet: {
        display: 'inline-block',
        margin: '0 2px',
        transform: 'scale(0.8)',
    },
    title: {
        fontSize: 14,
    },
    pos: {
        marginBottom: 12,
    },
});



function FacilitiesList() {

    const [facilities, setFacilities] = useState([]);
    const classes = useStyles();

    const fetchFacilities = async () => {

        const url = 'http://patientintake.shuthuluwhiskeyroses.com/api/location/';
        const response = await fetch(url);

        const facilities = await response.json();
        console.log(facilities);

        setFacilities(facilities);
    }

    useEffect(() => {
        fetchFacilities();
    }, []);


  return (
 
      <div>
          {facilities.map(facility =>

              <Card className={classes.paper}>
                      <CardContent>
                          <Typography className={classes.title} gutterBottom>
                             <h4> {facility.LocationDescription}</h4>
        </Typography>
                          <Typography variant="body2" color="textSecondary" component="p">
                           <br/>{facility.AddressLine1}
                           <br/>{facility.AddressLine2}
                           <br/>{facility.AddressCity}
                           <br/>{facility.AddressState}
                           <br/>{facility.AddressPostalCode}
                      </Typography>
                      <h4>Office Phone</h4>
                      <em>{facility.OfficePhone}</em>
                      <h4>Fax</h4>
                      <em>{facility.Fax}</em>
                      <h4>Notes</h4>
                      <em>{facility.Notes}</em>
                      </CardContent>
                      <CardActions>
                          <Link to={`/dashboard/${facility.Id}`}> <Button size="small">Learn More</Button></Link>
                      </CardActions>
                  </Card>
  
              
          )}
      </div>

  );
}

export default FacilitiesList;
